{"operation":"run_python","code":"from itertools import permutations

def mul(p,q):  # (p*q)(i) = p[q[i]]
    return tuple(p[q[i]] for i in range(4))

def pow_(p,n):
    r=(0,1,2,3)
    for _ in range(n):
        r=mul(r,p)
    return r

def order(p):
    r=(0,1,2,3); k=1
    while r!=(0,1,2,3):
        r=mul(r,p); k+=1
    return k

S4=[tuple(p) for p in permutations(range(4))]
print("size", len(S4))

# Method A: images of generator of C6 (domain C2 x C3 ~ C6): g^6 = e
A=[g for g in S4 if pow_(g,6)==(0,1,2,3)]
print("Method A count:", len(A))
from collections import Counter
print("orders among them:", Counter(order(g) for g in A))
print("all orders in S4:", Counter(order(g) for g in S4))

# Method B: direct generator description of C2 x C3:
# phi(x)=a with a^2=e, phi(y)=b with b^3=e, and a,b commute
E=(0,1,2,3)
inv=[g for g in S4 if mul(g,g)==E]
tri=[g for g in S4 if pow_(g,3)==E]
print("involutions+id:", len(inv), " order<=3 elements:", len(tri))
B=0
for a in inv:
    for b in tri:
        if mul(a,b)==mul(b,a):
            B+=1
print("Method B count:", B)

# Method C: brute force over ALL functions defined by generators, checking homomorphism on the whole group
# build C2 x C3 elements
G=[(i,j) for i in range(2) for j in range(3)]
def op(u,v): return ((u[0]+v[0])%2,(u[1]+v[1])%3)
count=0
for a in S4:
    for b in S4:
        # define phi(i,j) = a^i b^j ; check well-defined homomorphism
        ok=True
        vals={}
        for (i,j) in G:
            v=E
            for _ in range(i): v=mul(v,a)
            for _ in range(j): v=mul(v,b)
            vals[(i,j)]=v
        for u in G:
            for v in G:
                if mul(vals[u],vals[v])!=vals[op(u,v)]:
                    ok=False; break
            if not ok: break
        if ok: count+=1
print("Method C count (full check):", count)
