{"code":"from fractions import Fraction as F

def f(x):
    a, b = F(x), F(x+2)
    ea, eb = x+1, x+3          # integer exponents
    def pw(base, e):
        if e >= 0:
            return base**e
        return F(1) / base**(-e)   # base must be nonzero
    return pw(a, ea) * pw(b, eb)

vals = {x: f(x) for x in [0, -1, -2, -3]}
print("terms:", vals)
print("exact sum:", sum(vals.values()))
print("decimal sum:", float(sum(vals.values())))
print("10/9 as decimal:", 10/9)
"}

